const fs = require("fs");
const path = require("path");

const root = process.cwd();

const files = {
  "components/drivers/inspect-rides-panel.tsx": Buffer.from(
    "",
    "base64",
  ).toString("utf8"),
  "app/dashboard/drivers/page.tsx": Buffer.from(
    "",
    "base64",
  ).toString("utf8"),
};

const requiredMarkers = {
  "components/drivers/inspect-rides-panel.tsx": [
    "Inspect Rides interface preview",
    "Safety monitoring",
    "RouteMapPreview",
    "UI only",
  ],
  "app/dashboard/drivers/page.tsx": [
    "Driver applications",
    "Inspect rides",
    "InspectRidesPanel",
  ],
};

for (const [relativePath, source] of Object.entries(files)) {
  const targetPath = path.join(root, relativePath);
  const targetDirectory = path.dirname(targetPath);

  fs.mkdirSync(targetDirectory, { recursive: true });

  for (const marker of requiredMarkers[relativePath]) {
    if (!source.includes(marker)) {
      throw new Error(`Validation failed for ${relativePath}: ${marker}`);
    }
  }

  fs.writeFileSync(targetPath, source, "utf8");

  if (fs.readFileSync(targetPath, "utf8") !== source) {
    throw new Error(`Write verification failed for ${relativePath}`);
  }

  console.log(`Updated: ${relativePath}`);
}

console.log("");
console.log("Installed Inspect Rides UI preview.");
console.log("No Appwrite Function, database table, service or backend file was changed.");
console.log("Open /dashboard/drivers and select Inspect rides.");
